<?php
namespace App\Models;
use App\Models\Concerns\HasUuid; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo;
class VoiceEvent extends Model { use HasUuid; protected $fillable=['discord_guild_id','discord_channel_id','discord_user_id','type','payload','occurred_at']; protected function casts(): array{return ['payload'=>'array','occurred_at'=>'datetime'];} public static function pruneExpired(): int{return self::query()->where('occurred_at','<',now()->subDay())->delete();} public function label(): string{return match($this->type){'voice_join'=>'Arrivée','voice_leave'=>'Départ','voice_move'=>'Changement de salon','voice_mute'=>'Micro coupé','voice_unmute'=>'Micro réactivé','voice_deafen'=>'Sourdine activée','voice_undeafen'=>'Sourdine désactivée','screen_share_start'=>'Partage d’écran démarré','screen_share_stop'=>'Partage d’écran arrêté','bot_join'=>'Bot connecté','bot_leave'=>'Bot déconnecté',default=>$this->type};} public function tone(): string{return match($this->type){'voice_join','voice_unmute','screen_share_start','bot_join'=>'emerald','voice_leave','voice_mute','screen_share_stop','bot_leave'=>'slate','voice_move'=>'amber','voice_deafen','voice_undeafen'=>'sky',default=>'slate'};} public function actorName(): string{return data_get($this->payload,'display_name') ?: $this->discord_user_id ?: 'Système';} public function guild(): BelongsTo{return $this->belongsTo(DiscordGuild::class,'discord_guild_id');} public function channel(): BelongsTo{return $this->belongsTo(DiscordChannel::class,'discord_channel_id');} }
